// The JMAP-lite mail endpoints are read-only, so a processed mail cannot be flagged as seen.
// Track the newest receivedAt we have already handled instead, and ask only for what is newer.
const store = $getWorkflowStaticData('global');
const cfg = $input.first().json;

// first run: look one hour back rather than importing the whole mailbox as tickets
const since = store.lastSeenAt || new Date(Date.now() - 3600 * 1000).toISOString().replace(/\.\d+Z$/, 'Z');

return [{ json: { ...cfg, since } }];

// {"responses": {"<path>": {...}}, ...} -> one item per mail we have NOT filed yet.
//
// Two things rule out the obvious approaches:
//  - the JMAP-lite endpoints are read-only, so a handled mail cannot be flagged \Seen;
//  - filter[after] and filter[hasAttachment] are no-ops on the JmapShim (verified live: after
//    returns the whole mailbox even for a future timestamp).
// n8n's own static data is no help either - it is only persisted for production executions,
// so any manual run would re-import everything. The tickets are therefore the source of truth.
const listed = $('List new mail').first().json ?? {};
const known  = $input.first().json ?? {};
const cfg    = $('Since when?').first().json;
const store  = $getWorkflowStaticData('global');

const mailKey = e => `${cfg.mailAccount}:${cfg.mailFolder}:${e.id}`;

// every key already recorded on a ticket
const filed = new Set();
for (const t of Object.values(known.responses ?? {})) {
  for (const m of String(t.description ?? '').matchAll(/^Mail:\s+(\S+)/gm)) {
    filed.add(m[1]);
  }
}

const all = Object.values(listed.responses ?? {});
all.sort((a, b) => String(a.receivedAt ?? '').localeCompare(String(b.receivedAt ?? '')));

// ... and nothing older than "Since when?": one hour back on the very first run, so pointing the
// workflow at a full mailbox does not turn all of it into tickets
const fresh = all.filter(e => !filed.has(mailKey(e)) && String(e.receivedAt ?? '') >= cfg.since);

// keep the high-water mark up to date for production runs, where it does persist
if (fresh.length) store.lastSeenAt = fresh[fresh.length - 1].receivedAt;

return fresh.map(e => ({
  json: {
    emailId: e.id,
    mailKey: mailKey(e),
    receivedAt: e.receivedAt,
    egwBase: cfg.egwBase,
    egwUser: cfg.egwUser,
    egwQueue: cfg.egwQueue,
    llmModel: cfg.llmModel,
    classifierPrompt: cfg.classifierPrompt,
    mailAccount: cfg.mailAccount,
    mailFolder: cfg.mailFolder,
  },
}));

// JMAP Email -> the mail shape "Parse Email" already understands (it was written against the
// Gmail Trigger's output), so the whole downstream pipeline is reused unchanged.
const e = $input.item.json ?? {};
const meta = $('Split new mail').item.json;

const from = (e.from ?? [])[0] ?? {};

// prefer the text/plain part; fall back to whatever bodyValues holds, then to the preview
const values = e.bodyValues ?? {};
const textPartId = (e.textBody ?? [])[0]?.partId;
const body =
  (textPartId && values[textPartId]?.value) ||
  Object.values(values)[0]?.value ||
  e.preview ||
  '';

return {
  json: {
    id: e.id,
    threadId: e.threadId ?? e.id,
    subject: e.subject ?? '(no subject)',
    from: { value: [{ address: from.email ?? '', name: from.name ?? '' }], text: from.email ?? '' },
    date: e.sentAt ?? e.receivedAt ?? new Date().toISOString(),
    textPlain: body,
    egwBase: meta.egwBase,
    egwUser: meta.egwUser,
    egwQueue: meta.egwQueue,
    llmModel: meta.llmModel,
    classifierPrompt: meta.classifierPrompt,
    // everything the attachment round trip needs later on
    mailMeta: {
      emailId: e.id,
      mailKey: meta.mailKey,
      mailAccount: meta.mailAccount,
      mailFolder: meta.mailFolder,
      attachments: (e.attachments ?? []).map(a => ({
        blobId: a.blobId,
        name: a.name || (a.blobId + '.bin'),
        type: a.type || 'application/octet-stream',
      })),
    },
  },
};

const m = $input.item.json;

const subject = String(m.subject ?? m.Subject ?? '(no subject)');
const from = m.from?.value?.[0]?.address ?? m.from?.text ?? m.From ?? '';
const fromName = m.from?.value?.[0]?.name ?? '';
const date = m.date ?? m.Date ?? new Date().toISOString();
const body = String(m.textPlain ?? m.text ?? m.snippet ?? '').replace(/\r\n/g, '\n').trim();

// Does the subject reference an existing ticket?  e.g. "Re: [#42] printer broken"
const ref = subject.match(/\[#(\d+)\]/);
const ticketId = ref ? parseInt(ref[1], 10) : null;

// Clean title: drop the [#id] token and any Re:/Fwd:/Aw: prefixes
const title = subject
  .replace(/\[#\d+\]/g, '')
  .replace(/^\s*((re|fwd|fw|aw|tr)\s*:\s*)+/i, '')
  .trim() || '(no subject)';

// Tracker priority is 1..9, 5 = medium
const haystack = subject + ' ' + body;
const urgent = /\b(urgent|asap|critical|outage|blocker|emergency|down)\b/i.test(haystack);
const low = /\b(question|fyi|info|low priority)\b/i.test(subject);
const priority = urgent ? 8 : low ? 3 : 5;

const sender = fromName ? fromName + ' (' + from + ')' : from;
const header = ['From:  ' + sender, 'Date:  ' + date, 'Mail:  ' + ((m.mailMeta && m.mailMeta.mailKey) || m.id || '')].join('\n');

const cfg = m;   // carried through by "To mail shape"

return {
  json: {
    isReply: ticketId !== null,
    ticketId,
    title,
    priority,
    // full mail for a new ticket's description
    description: header + '\n' + '-'.repeat(60) + '\n\n' + body,
    // shorter form for a reply on an existing ticket
    replyMessage: 'Mail from ' + sender + ' (' + date + '):\n' +
      'Mail:  ' + ((m.mailMeta && m.mailMeta.mailKey) || m.id || '') + '\n\n' + body,
    gmailId: m.id ?? null,
    threadId: m.threadId ?? null,
    replyTo: from,
    subject,
    egwBase: cfg.egwBase,
    egwUser: cfg.egwUser,
    egwQueue: cfg.egwQueue,
    mailMeta: m.mailMeta ?? null,
    bodyText: body,
    llmModel: cfg.llmModel,
    classifierPrompt: cfg.classifierPrompt,
  },
  binary: $input.item.binary,
};

const res = $input.item.json ?? {};
const mail = $('Parse Email').item.json;
const status = res.statusCode ?? null;

if (status !== 201 && status !== 204) {
  throw new Error(
    'Adding a reply to ticket #' + mail.ticketId + ' failed: HTTP ' + status +
    ' ' + JSON.stringify(res.body ?? '')
  );
}

// The reply is stored, but nothing yet records WHICH mail produced it - and "Split new mail"
// only knows a mail is handled when its key appears in a ticket description. Without this the
// same reply mail is picked up again on the very next poll, forever.
const ticket = $('GET ticket').item.json.body ?? {};
const key = mail.mailMeta && mail.mailMeta.mailKey;
const description = String(ticket.description ?? '');
const alreadyRecorded = key && description.includes('Mail:  ' + key);

return {
  json: {
    ticketId: mail.ticketId,
    created: false,
    egwBase: mail.egwBase,
    egwUser: mail.egwUser,
    title: mail.title,
    replyTo: mail.replyTo,
    threadId: mail.threadId,
    mailMeta: mail.mailMeta ?? null,
    needsMarker: !!key && !alreadyRecorded,
    // the description the marker gets appended to
    patch: { description: description + '\nMail:  ' + key },
  },
  binary: $('Parse Email').item.binary,
};

const res = $input.item.json ?? {};
const mail = $('Parse Email').item.json;

const headers = res.headers ?? {};
const location = headers.location ?? headers.Location ?? '';
const m = String(location).match(/\/(\d+)\/?$/);
const ticketId = m ? parseInt(m[1], 10) : null;

if (!ticketId) {
  throw new Error(
    'Tracker returned no ticket id. HTTP ' + (res.statusCode ?? '?') +
    ' Location="' + location + '" body=' + JSON.stringify(res.body ?? '')
  );
}

return {
  json: {
    ticketId,
    created: true,
    egwBase: mail.egwBase,
    egwUser: mail.egwUser,
    title: mail.title,
    replyTo: mail.replyTo,
    threadId: mail.threadId,
    mailMeta: mail.mailMeta ?? null,
  },
  binary: $('Parse Email').item.binary,
};

// one item per JMAP attachment reference - the bytes are fetched by the next node
const out = [];

for (const item of $input.all()) {
  const meta = item.json.mailMeta ?? {};
  for (const a of meta.attachments ?? []) {
    out.push({
      json: {
        ticketId: item.json.ticketId,
        egwBase: item.json.egwBase,
        egwUser: item.json.egwUser,
        mailAccount: meta.mailAccount,
        mailFolder: meta.mailFolder,
        emailId: meta.emailId,
        blobId: a.blobId,
        fileName: a.name,
        mimeType: a.type,
      },
    });
  }
}

return out;

const mail = $('Parse Email').item.json;
const res  = $input.item.json ?? {};

// queue labels -> tracker ids (Admin > Tracker), from Config - ids differ between installations
let QUEUES = {};
try { QUEUES = JSON.parse($('Config').first().json.queueIds || '{}'); } catch (e) {}

let c = null;
try {
  let raw = res.body?.choices?.[0]?.message?.content ?? '';
  raw = String(raw).replace(/^```(?:json)?/m, '').replace(/```\s*$/m, '').trim();
  c = JSON.parse(raw);
} catch (e) {
  c = null;                        // fall back to Parse Email's keyword guess
}

const queueId  = c && QUEUES[c.queue] ? QUEUES[c.queue]
               : (mail.egwQueue ? Number(mail.egwQueue) : null);
const priority = c && Number.isInteger(c.priority) && c.priority >= 1 && c.priority <= 9
               ? c.priority : mail.priority;
const title    = c && c.title ? String(c.title).slice(0, 70) : mail.title;

// keep the triage visible at the top of the ticket so a human can sanity-check it
const triage = c
  ? ['Triage: ' + (c.queue ?? '?') + ' / priority ' + priority + ' / ' + (c.language ?? '?'),
     c.summary ? 'Summary: ' + c.summary : null].filter(Boolean).join('\n') + '\n\n'
  : 'Triage: LLM unavailable, fell back to keyword rules\n\n';

return {
  json: {
    ...mail,
    title,
    priority,
    trackerId: queueId,
    llmCategory: (c && c.category) || null,
    classified: c !== null,
    description: triage + mail.description,
  },
  binary: $('Parse Email').item.binary,
};

// The reply branch has no "Mail: <key>" marker in a ticket description to prove a mail was
// handled, and PATCH cannot add one - it ignores description silently (204, unchanged). But
// GET ticket, right before this, already returns the ticket's replies, so the marker lives in
// the reply text instead and is checked here for free.
//
// Without this the schedule re-posts the same reply every minute: manual runs never showed it,
// an active workflow produced 13 copies in 13 minutes.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const mail = $('Parse Email').itemMatching(i).json;
  const ticket = items[i].json.body ?? {};
  const key = (mail.mailMeta && mail.mailMeta.mailKey) || mail.id || '';

  const alreadyThere = Object.values(ticket.replies ?? {}).some(
    r => String(r.message ?? '').includes('Mail:  ' + key)
  );

  if (!alreadyThere) {
    out.push({ json: mail, binary: $('Parse Email').itemMatching(i).binary });
  }
}

// an empty array simply ends the branch - "nothing new to reply to" is not an error
return out;
